  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1

* --- Stimulus ---
* Common mode is 500mV. Step is +/- 200mV.
V_vip vip 0 DC 0.5 AC 0.5 PULSE(0.3 0.7 5n 100p 100p 20n 40n)
V_vim vim 0 DC 0.5 AC -0.5 PULSE(0.7 0.3 5n 100p 100p 20n 40n)

* --- Analyses ---
.control
  * 1. DC Operating Point
  op
  let i_q = -i(VDD)
  print i_q

  * 2. AC Analysis (Extract Open-Loop Gain from Closed-Loop Error Signal)
  ac dec 100 1 1G
  let out_diff = v(vop) - v(vom)
  let in_diff = v(vp) - v(vm)
  let A_OL = out_diff / in_diff
  let A_OL_db = 20 * log10(mag(A_OL))
  meas ac dc_gain_db find A_OL_db at=10

  * 3. Transient Analysis
  tran 10p 30n
  * Measure Slew Rate during the rising transition (around 5ns)
  meas tran sr_rise deriv v(vop) when v(vop)=0.5 rise=1

  * Measure Settling Time (Time to reach within ~1.5% of final 0.7V value)
  meas tran t_cross when v(vop)=0.69 rise=1
  let t_settle = t_cross - 5n
  print t_settle
.endc
.end

